/* i386 / x86_64 Objective-C method signatures of the SDK methods the game uses.
 *
 * The table lives in objc_sigs_gen.c, generated by tools/gen_objc_sigs.py from
 * the macOS SDK headers (clang computes the encodings for both targets).
 * i386_types is the classic 32-bit encoding with frame offsets, e.g.
 * "v28@0:4{_NSRect={_NSPoint=ff}{_NSSize=ff}}8c24" for -[NSWindow
 * setFrame:display:]; x64_types is the same method for x86_64.  Either may be
 * NULL when the method is not declared for that architecture.
 *
 * container is the declaring class (methods of categories are filed under
 * their class) or protocol (delegates, data sources, NSObject, NSCopying...).
 */
#ifndef DX_OBJC_SIGS_H
#define DX_OBJC_SIGS_H

#include <stddef.h>

struct objc_sig {
    const char *container;
    const char *selector;
    unsigned char is_class_method;
    const char *i386_types;
    const char *x64_types;
};

/* Exact declaration (container, selector, kind), or NULL. */
const struct objc_sig *objc_sig_lookup(const char *container, const char *selector, int is_class_method);

/* Any declaration of the selector with an i386 encoding: if the declarations
 * disagree, the most common i386 encoding wins and *conflict is set to 1.
 * conflict may be NULL. */
const struct objc_sig *objc_sig_lookup_any_ex(const char *selector, int is_class_method, int *conflict);
const struct objc_sig *objc_sig_lookup_any(const char *selector, int is_class_method);

/* SDK superclass of cls (only for classes in the table / hr-classrefs.txt and
 * their superclass chains), or NULL. */
const char *objc_sig_superclass(const char *cls);

/* Walks cls and its SDK superclasses with objc_sig_lookup; falls back to
 * objc_sig_lookup_any (protocol methods, unknown classes). */
const struct objc_sig *objc_sig_lookup_inherited(const char *cls, const char *selector, int is_class_method);

/* Whole table (sorted by selector, container, is_class_method). */
const struct objc_sig *objc_sig_table(size_t *count);

#endif
